#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;

    const long long MOD = 1000000007LL;
    vector<long long> stack = {0};
    for (char ch : s) {
        if (ch == '(') {
            stack.push_back(0);
        } else {
            long long inner = stack.back();
            stack.pop_back();
            stack.back() = (stack.back() + max(2 * inner % MOD, 1LL)) % MOD;
        }
    }
    cout << stack[0] % MOD << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        final long MOD = 1000000007L;
        long[] stack = new long[s.length() + 1];
        int size = 1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack[size++] = 0;
            } else {
                long inner = stack[--size];
                stack[size - 1] = (stack[size - 1] + Math.max(2 * inner % MOD, 1)) % MOD;
            }
        }
        System.out.println(stack[0] % MOD);
    }
}
